argv:
set timeout 90
proc fail {code} {
  catch {send -- "\\003"}
  after 300
  catch {close}
  catch {wait}
  exit $code
}
spawn env QWEN_TUI_RENDERER=opentui QWEN_CODE_SKIP_UPDATE_CHECK_ONCE=true bun packages/cli/dist/index.js
expect {
  -re {ready} {}
  -re {TextNodeRenderable only accepts|unexpected critical error|Error:} { fail 1 }
  timeout { fail 2 }
}
send -- "/help\\r"
expect {
  -re {For.*more help:} {}
  -re {TextNodeRenderable only accepts|unexpected critical error|Error:} { fail 3 }
  timeout { fail 4 }
}
send -- "\\033"
expect {
  -re {Ask.*anything} {}
  -re {TextNodeRenderable only accepts|unexpected critical error|Error:} { fail 5 }
  timeout { fail 6 }
}
send -- "\\003"
expect {
  eof {}
  timeout { fail 7 }
}
